PRAGMA foreign_keys=ON;
CREATE TABLE data_sources(source_id TEXT PRIMARY KEY,name TEXT NOT NULL,domain TEXT NOT NULL,authority_level TEXT NOT NULL CHECK(authority_level IN('PRIMARY','SECONDARY')),access_status TEXT NOT NULL CHECK(access_status IN('VERIFIED_AUTOMATED','VERIFIED_MANUAL','PARTIAL','RESTRICTED','UNKNOWN','UNAVAILABLE')),configuration_json TEXT NOT NULL DEFAULT '{}',UNIQUE(name,domain));
CREATE TABLE ingestion_runs(run_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES data_sources,started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL CHECK(status IN('RUNNING','SUCCEEDED','PARTIAL','FAILED')),records_processed INTEGER NOT NULL DEFAULT 0,errors INTEGER NOT NULL DEFAULT 0,parser_version TEXT NOT NULL,error_details TEXT);
CREATE TABLE raw_documents(document_id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES data_sources,run_id TEXT NOT NULL REFERENCES ingestion_runs,source_url TEXT NOT NULL,retrieved_at TEXT NOT NULL,publication_at TEXT,media_type TEXT NOT NULL,sha256 TEXT NOT NULL CHECK(length(sha256)=64),storage_path TEXT NOT NULL,UNIQUE(source_url,retrieved_at));
CREATE TRIGGER raw_documents_no_update BEFORE UPDATE ON raw_documents BEGIN SELECT RAISE(ABORT,'raw documents are immutable'); END;
CREATE TRIGGER raw_documents_no_delete BEFORE DELETE ON raw_documents BEGIN SELECT RAISE(ABORT,'raw documents are immutable'); END;
CREATE TABLE issuers(issuer_id TEXT PRIMARY KEY,legal_name TEXT NOT NULL,short_name TEXT,tax_identifier TEXT,registration_identifier TEXT,openinfo_identifier TEXT,exchange_identifier TEXT,depository_identifier TEXT,lei TEXT,sector TEXT,industry TEXT,resolution_method TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE issuer_name_history(issuer_name_id TEXT PRIMARY KEY,issuer_id TEXT NOT NULL REFERENCES issuers,name TEXT NOT NULL,name_type TEXT NOT NULL CHECK(name_type IN('LEGAL','SHORT','HISTORICAL','SOURCE_DISPLAY')),valid_from TEXT,valid_to TEXT,known_at TEXT NOT NULL,document_id TEXT NOT NULL REFERENCES raw_documents,CHECK(valid_to IS NULL OR valid_from IS NULL OR valid_to>=valid_from),UNIQUE(issuer_id,name,name_type,known_at));
CREATE TABLE security_classes(security_class_code TEXT PRIMARY KEY,display_name TEXT NOT NULL);
INSERT INTO security_classes VALUES('COMMON','Common share'),('PREFERRED','Preferred share'),('OTHER','Other'),('UNKNOWN','Unknown');
CREATE TABLE securities(security_id TEXT PRIMARY KEY,issuer_id TEXT NOT NULL REFERENCES issuers,security_class_code TEXT NOT NULL REFERENCES security_classes,security_type TEXT NOT NULL DEFAULT 'EQUITY',nominal_value TEXT,currency TEXT,created_at TEXT NOT NULL);
CREATE TABLE listings(listing_id TEXT PRIMARY KEY,security_id TEXT NOT NULL REFERENCES securities,exchange_code TEXT NOT NULL,board_code TEXT,listing_status TEXT NOT NULL CHECK(listing_status IN('ACTIVE','DELISTED','SUSPENDED','UNKNOWN')),listing_date TEXT,delisting_date TEXT,known_at TEXT NOT NULL,document_id TEXT NOT NULL REFERENCES raw_documents,CHECK(delisting_date IS NULL OR listing_date IS NULL OR delisting_date>=listing_date),UNIQUE(security_id,exchange_code,known_at));
CREATE TABLE identifier_history(identifier_id TEXT PRIMARY KEY,entity_type TEXT NOT NULL CHECK(entity_type IN('ISSUER','SECURITY')),issuer_id TEXT REFERENCES issuers,security_id TEXT REFERENCES securities,identifier_type TEXT NOT NULL,identifier_value TEXT NOT NULL,valid_from TEXT,valid_to TEXT,known_at TEXT NOT NULL,document_id TEXT NOT NULL REFERENCES raw_documents,CHECK((entity_type='ISSUER' AND issuer_id IS NOT NULL AND security_id IS NULL) OR(entity_type='SECURITY' AND security_id IS NOT NULL AND issuer_id IS NULL)),CHECK(valid_to IS NULL OR valid_from IS NULL OR valid_to>=valid_from),UNIQUE(entity_type,identifier_type,identifier_value,known_at));
CREATE INDEX identifier_lookup ON identifier_history(identifier_type,identifier_value,known_at);
CREATE TABLE resolution_conflicts(conflict_id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES ingestion_runs,candidate_type TEXT NOT NULL,candidate_value TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'UNRESOLVED' CHECK(status IN('UNRESOLVED','RESOLVED','REJECTED')),created_at TEXT NOT NULL);
